-- learning-service: one lesson-plan item per scheduled class of every subject, and study sessions
-- Ask 46 baseline seed, exported from the running stack by scripts/export_seed.py (Flyway reset). Edit by hand or re-export.

SELECT setval(pg_get_serial_sequence('lesson_plan_item', 'id'), COALESCE((SELECT max(id) FROM lesson_plan_item), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('study_session', 'id'), COALESCE((SELECT max(id) FROM study_session), 0) + 1, false);
